"Sorry to hear that. A fresh symptom check can look at what's changed. If you have trouble breathing, chest pain, confusion or heavy bleeding, please get care today.": "यह सुनकर दुख हुआ। नई लक्षण जाँच से पता चल सकता है कि क्या बदला है। अगर साँस लेने में तकलीफ़, सीने में दर्द, भ्रम या ज़्यादा खून बह रहा हो, तो आज ही इलाज करवाएँ।",
"Thanks — that helps keep your health score accurate. 💛": "धन्यवाद! इससे आपका हेल्थ स्कोर सही रहता है। 💛",
"Thanks. I'll ask again in a couple of days.": "धन्यवाद। मैं एक-दो दिन में फिर पूछूँगा।",
"Wonderful, glad you're feeling better! 🎉 I've taken it off your ongoing list.": "बहुत अच्छा, आप बेहतर महसूस कर रहे हैं! 🎉 मैंने इसे आपकी चालू सूची से हटा दिया है।",
"You breathe roughly 22,000 times a day, on autopilot.": "आप दिन में लगभग 22,000 बार साँस लेते हैं, बिना सोचे।",
"Your resting pulse tends to be lowest right after you wake up.": "आराम की हालत में आपकी नब्ज़ आमतौर पर सुबह उठते ही सबसे कम होती है।",
"Back to my space": "मेरी जगह पर वापस",
