"Red blood cells ferry oxygen to every living cell in you.": "लाल रक्त कोशिकाएँ आपके शरीर की हर जीवित कोशिका तक ऑक्सीजन पहुँचाती हैं।",
"Something went wrong. Please try again.": "कुछ गड़बड़ हो गई। कृपया फिर कोशिश करें।",
"Your lungs hold a surface area the size of a tennis court.": "आपके फेफड़ों की सतह का क्षेत्रफल एक टेनिस कोर्ट जितना होता है।",
"A few basics so QueroCura knows who it's caring for.": "कुछ बुनियादी बातें, ताकि QueroCura जान सके कि वह किसका ख़याल रख रहा है।",
"Active already — love it! 💪": "पहले से सक्रिय हैं, बहुत बढ़िया! 💪",
