"Another food allergy — press Enter or tap Add": "खाने की कोई और एलर्जी, Enter दबाएँ या जोड़ें पर टैप करें",
"Another medication allergy — press Enter or tap Add": "किसी और दवा से एलर्जी, Enter दबाएँ या जोड़ें पर टैप करें",
"Another ongoing condition — press Enter or tap Add": "कोई और चालू बीमारी, Enter दबाएँ या जोड़ें पर टैप करें",
"Another past condition or surgery — press Enter or tap Add": "कोई और पुरानी बीमारी या सर्जरी, Enter दबाएँ या जोड़ें पर टैप करें",
"Any allergies?": "कोई एलर्जी है?",
"Biological sex": "जैविक लिंग",
"Both matter: ongoing conditions and the ones you've left behind.": "दोनों मायने रखती हैं: चालू बीमारियाँ और जो पीछे छूट चुकी हैं।",
