"Finish & go to dashboard ✨": "पूरा करें और डैशबोर्ड पर जाएँ ✨",
"From 40 on, heart and diabetes history in the family really count. ❤️": "40 के बाद परिवार में दिल की बीमारी और डायबिटीज़ का इतिहास काफ़ी मायने रखता है। ❤️",
"Got it — I'll keep": "समझ गया, मैं रखूँगा:",
"Hi, I'm Cura! I'll keep this quick — about a minute.": "नमस्ते, मैं Cura हूँ! मैं इसे जल्दी निपटा दूँगा, बस एक मिनट।",
"How do you live?": "आपकी जीवनशैली कैसी है?",
"Last stop! Check it over and we're done.": "आख़िरी पड़ाव! एक बार देख लें और हम पूरे हुए।",
"Let's get acquainted": "चलिए, जान-पहचान करें",
"Lifestyle shapes risk and the advice you receive.": "जीवनशैली से जोखिम तय होता है और आपको मिलने वाली सलाह भी।",
"Medicines & family health": "दवाइयाँ और परिवार की सेहत",
"Nice to meet you,": "आपसे मिलकर अच्छा लगा,",
