"Review & finish": "देखें और पूरा करें",
"Thank you for being honest. It nudges your health score — and quitting moves it back up. 🌱": "सच बताने के लिए धन्यवाद। इससे आपका हेल्थ स्कोर थोड़ा घटता है, और छोड़ देने पर फिर बढ़ जाता है। 🌱",
