"That age doesn't look right — double-check it?": "यह उम्र सही नहीं लग रही। एक बार फिर देख लें?",
"Under 18? Symptom checks use child-specific guidance for you. 🧒": "18 से कम उम्र? लक्षण जाँच में आपके लिए बच्चों के हिसाब से मार्गदर्शन इस्तेमाल होता है। 🧒",
"We use this to keep every recommendation safer.": "हम इसका इस्तेमाल हर सुझाव को ज़्यादा सुरक्षित बनाने के लिए करते हैं।",
"What should we call you?": "हम आपको क्या कहकर बुलाएँ?",
