"A hospital can only see your QueroCura data if you say yes. You choose what they see and for how long, and you can switch it off in one tap. Everything they do is listed below.": "कोई अस्पताल आपका QueroCura डेटा तभी देख सकता है जब आप हाँ कहें। आप तय करते हैं कि वे क्या देखें और कितने समय तक, और एक टैप में इसे बंद कर सकते हैं। उनकी हर कार्रवाई नीचे सूची में है।",
