"Pick what to share, make a code, and read it out or show it to the hospital staff. It works once and stops working after an hour.": "चुनें कि क्या साझा करना है, कोड बनाएँ और अस्पताल के स्टाफ़ को बोलकर बताएँ या दिखाएँ। यह एक बार चलता है और एक घंटे बाद बंद हो जाता है।",
"Records added by your care teams": "आपकी केयर टीमों द्वारा जोड़े गए रिकॉर्ड",
"Valid for 1 hour, once. Share it only with the person helping you.": "1 घंटे के लिए, सिर्फ़ एक बार मान्य। इसे सिर्फ़ उसी व्यक्ति को बताएँ जो आपकी मदद कर रहा है।",
