"No worries. Enter the e-mail you signed up with and we'll send a link to choose a new one. It works once and expires in an hour.": "कोई बात नहीं। जिस ई-मेल से आपने खाता बनाया था वह डालें, हम नया पासवर्ड चुनने का लिंक भेजेंगे। यह एक बार चलता है और एक घंटे में ख़त्म हो जाता है।",
