"A detailed summary of the patient's medical information reaches first responders immediately — biometrically verified, nothing to fill out.": "मरीज़ की मेडिकल जानकारी का पूरा सारांश तुरंत पहली मदद करने वालों तक पहुँचता है। बायोमेट्रिक से पक्का किया हुआ, कुछ भरना नहीं पड़ता।",
"A few things people ask.": "कुछ बातें जो लोग पूछते हैं।",
"A fingerprint or iris is scanned": "उँगली का निशान या आँख की पुतली स्कैन होती है",
"A medical emergency happens": "कोई मेडिकल इमरजेंसी होती है",
"A medical professional scans the patient's fingerprint or iris — no forms, no delay.": "कोई मेडिकल पेशेवर मरीज़ की उँगली का निशान या पुतली स्कैन करता है। न फ़ॉर्म, न देरी।",
"A project which aims to increase the speed of medical response for a patient who reaches the hospital in an emergency situation.": "एक परियोजना जिसका मक़सद इमरजेंसी में अस्पताल पहुँचे मरीज़ के लिए इलाज की रफ़्तार बढ़ाना है।",
"A starting point for the clinical interview that follows": "आगे होने वाली क्लिनिकल बातचीत की शुरुआत",
"A sudden weight drop, a creeping blood pressure, a condition that keeps coming back — QueroCura compares each reading with": "अचानक वज़न घटना, धीरे-धीरे बढ़ता ब्लड प्रेशर, बार-बार लौटती कोई बीमारी। QueroCura हर रीडिंग को इससे मिलाता है:",
"A world where no patient's history is a mystery to the people trying to save them — and where staying on top of your own health is as simple as checking your phone.": "ऐसी दुनिया जहाँ जान बचाने वालों के लिए किसी मरीज़ का इतिहास अनजान न हो, और जहाँ अपनी सेहत पर नज़र रखना फ़ोन देखने जितना आसान हो।",
"ABOUT QUEROCURA": "QUEROCURA के बारे में",
"About": "हमारे बारे में",
"Access": "एक्सेस",
"Access is simply denied. Nothing about the patient is shown or exposed either way — a failed match looks identical to no record existing at all.": "एक्सेस बस नामंज़ूर हो जाता है। मरीज़ के बारे में कुछ भी दिखाया या उजागर नहीं होता। मिलान न होना ऐसा दिखता है जैसे कोई रिकॉर्ड ही नहीं है।",
"Addressing the elephant in the room — how do we keep your data safe?": "सबसे बड़े सवाल पर बात करें: हम आपका डेटा सुरक्षित कैसे रखते हैं?",
"After a symptom check you get a clear triage level, what's safe to do at home, what to avoid, and exactly when to see a doctor. We never recommend medicines — that's for you and a pharmacist.": "लक्षण जाँच के बाद आपको साफ़ ट्राइएज स्तर मिलता है, कि घर पर क्या करना सुरक्षित है, किससे बचना है, और डॉक्टर को कब दिखाना है। हम कभी दवाइयाँ नहीं सुझाते। वह आपका और फ़ार्मासिस्ट का काम है।",
"Analyzed over time, so trends surface on their own": "समय के साथ विश्लेषण होता है, इसलिए रुझान अपने-आप उभर आते हैं",
