"To close the gap between what's known about a patient and what's in reach — putting the right health information in the right hands, at the moment it matters most.": "मरीज़ के बारे में जो ज्ञात है और जो पहुँच में है, उसके बीच का फ़ासला मिटाना, यानी सही सेहत जानकारी को सही हाथों में सबसे ज़रूरी पल पर पहुँचाना।",
