"Who decides what's shown?": "क्या दिखाया जाए, यह कौन तय करता है?",
"Who's allowed to enter my medical information?": "मेरी मेडिकल जानकारी कौन डाल सकता है?",
"Works off prescriptions already stored in CuraVault": "CuraVault में पहले से रखे पर्चों के आधार पर काम करता है",
"You might ask, how do we decide what information to display in an emergency?": "आप पूछ सकते हैं कि इमरजेंसी में कौन-सी जानकारी दिखानी है, यह हम कैसे तय करते हैं?",
"Your data is yours — encrypted, and shown only when it needs to be.": "आपका डेटा आपका है, एन्क्रिप्टेड, और सिर्फ़ तभी दिखता है जब ज़रूरत हो।",
"Your health, watched over — gently.": "आपकी सेहत पर नज़र, नरमी से।",
"Your score is built from your vitals, symptom checks, conditions and lifestyle — and it's identical everywhere you see it, with a plain-language breakdown of why.": "आपका स्कोर आपके वाइटल्स, लक्षण जाँचों, बीमारियों और जीवनशैली से बनता है। आप इसे जहाँ भी देखें वह एक जैसा रहता है, और आसान भाषा में कारण भी बताया जाता है।",
