"Some of your answers can signal an emergency. Call your local emergency number (112 in India) or go to the nearest emergency department now. You can still see the analysis below.": "आपके कुछ जवाब इमरजेंसी का संकेत हो सकते हैं। अपने इलाक़े का इमरजेंसी नंबर (भारत में 112) मिलाएँ या अभी सबसे नज़दीकी इमरजेंसी विभाग जाएँ। विश्लेषण आप नीचे फिर भी देख सकते हैं।",
