"💜 <b>You matter, and you don't have to face this alone.</b> If you're thinking about harming yourself, please reach out right now — in India call <b>Tele-MANAS 14416</b> or <b>KIRAN 1800-599-0019</b> (free, 24/7), or your local emergency number.": "💜 <b>आप मायने रखते हैं, और आपको इसका सामना अकेले नहीं करना है।</b> अगर आप अपने को नुक़सान पहुँचाने के बारे में सोच रहे हैं, तो कृपया अभी संपर्क करें। भारत में <b>Tele-MANAS 14416</b> या <b>KIRAN 1800-599-0019</b> पर कॉल करें (मुफ़्त, 24 घंटे), या अपने इलाक़े का इमरजेंसी नंबर मिलाएँ।",
"Some of the answers you gave can be signs of an emergency.": "आपके दिए कुछ जवाब इमरजेंसी के संकेत हो सकते हैं।",
"Call your local emergency number (112 in India) or go to the nearest emergency department now.": "अपने इलाक़े का इमरजेंसी नंबर (भारत में 112) मिलाएँ या अभी सबसे नज़दीकी इमरजेंसी विभाग जाएँ।",
"The analysis below is for information and is not a substitute for urgent care.": "नीचे का विश्लेषण सिर्फ़ जानकारी के लिए है, तुरंत इलाज का विकल्प नहीं।",
"Some of the answers you gave can be signs of an emergency. <strong>Call your local emergency number (112 in India) or go to the nearest emergency department now.</strong> The analysis below is for information and is not a substitute for urgent care. <a>Call 112</a>": "आपके दिए कुछ जवाब इमरजेंसी के संकेत हो सकते हैं। <strong>अपने इलाक़े का इमरजेंसी नंबर (भारत में 112) मिलाएँ या अभी सबसे नज़दीकी इमरजेंसी विभाग जाएँ।</strong> नीचे का विश्लेषण सिर्फ़ जानकारी के लिए है, तुरंत इलाज का विकल्प नहीं। <a>112 पर कॉल करें</a>",
"Seek care now if you notice": "इनमें से कुछ दिखे तो अभी इलाज लें",
