", so you can always see what's been flagged. In a day or two I'll ask how you're feeling, and once you say you're better it comes off your ongoing list. It's a possibility, not a diagnosis. Already living with": ", ताकि आप हमेशा देख सकें कि क्या चिह्नित हुआ। एक-दो दिन में मैं पूछूँगा कि आप कैसा महसूस कर रहे हैं, और जब आप बताएँगे कि बेहतर हैं तो यह आपकी चालू सूची से हट जाएगा। यह एक संभावना है, निदान नहीं। अगर पहले से यह है:",
