"Import the calendar file and enable alarms in your calendar app. Exports include up to one year of future doses or the treatment end, whichever is earlier. After a schedule change, update or replace the imported events. In-app reminders work while CuraVault is active.": "कैलेंडर फ़ाइल इम्पोर्ट करें और अपने कैलेंडर ऐप में अलार्म चालू करें। एक्सपोर्ट में आगे की एक साल तक की खुराकें या इलाज का अंत, जो पहले हो, शामिल है। शेड्यूल बदलने पर इम्पोर्ट किए इवेंट अपडेट या बदलें। ऐप के रिमाइंडर तब काम करते हैं जब CuraVault चालू हो।",
