"Prepared from what you logged in QueroCura. It is a memory aid for you and your doctor, not a diagnosis or medical advice.": "यह QueroCura में दर्ज आपकी जानकारी से तैयार किया गया है। यह आपके और आपके डॉक्टर के लिए याददाश्त की मदद है, निदान या चिकित्सा सलाह नहीं।",
"Send this to your doctor": "इसे अपने डॉक्टर को भेजें",
"Make a private link (and QR code) so your doctor can read a one-page brief before you walk in. Only you choose what is in it, it needs a PIN, it stops working on its own, and you can switch it off any time.": "एक निजी लिंक (और QR कोड) बनाएँ, ताकि आपके डॉक्टर आपके पहुँचने से पहले एक पन्ने का संक्षिप्त ब्योरा पढ़ सकें। उसमें क्या होगा यह सिर्फ़ आप तय करते हैं, उसके लिए PIN चाहिए, वह अपने आप बंद हो जाता है, और आप उसे कभी भी बंद कर सकते हैं।",
