"Acid Reflux (GERD)": "एसिड रिफ़्लक्स (GERD)",
"General physician / Gastroenterologist": "जनरल फ़िज़िशियन / गैस्ट्रोएंटेरोलॉजिस्ट",
"Gastritis / Peptic Ulcer": "गैस्ट्राइटिस / पेप्टिक अल्सर",
"Possible Appendicitis": "संभावित एपेंडिसाइटिस",
"General surgeon / Emergency department": "जनरल सर्जन / इमरजेंसी विभाग",
"Gallbladder Problem (Gallstones)": "पित्ताशय की समस्या (पथरी)",
"General surgeon / Gastroenterologist": "जनरल सर्जन / गैस्ट्रोएंटेरोलॉजिस्ट",
"Possible Ectopic Pregnancy or Miscarriage": "संभावित एक्टोपिक गर्भावस्था या गर्भपात",
"Gynaecologist / Emergency department": "स्त्री रोग विशेषज्ञ / इमरजेंसी विभाग",
"Possible Testicular Torsion": "संभावित अंडकोष का मुड़ना (टॉर्शन)",
"Emergency department / Urologist": "इमरजेंसी विभाग / यूरोलॉजिस्ट",
"Possible Bleeding from the Stomach or Bowel": "आमाशय या आँत से संभावित ख़ून बहना",
"Emergency department / Gastroenterologist": "इमरजेंसी विभाग / गैस्ट्रोएंटेरोलॉजिस्ट",
"Hepatitis (Liver Infection)": "हेपेटाइटिस (लिवर का संक्रमण)",
"General physician / Hepatologist": "जनरल फ़िज़िशियन / हेपेटोलॉजिस्ट",
"Urinary Tract Infection (Bladder Infection)": "मूत्र मार्ग का संक्रमण (मूत्राशय का संक्रमण)",
