"enlarged": "बढ़ा हुआ",
"Albumin": "एल्बुमिन",
"Basophils": "बेसोफ़िल",
"Calcium": "कैल्शियम",
"Chloride": "क्लोराइड",
"Eosinophils": "ईओसिनोफ़िल",
