"Statins": "स्टैटिन",
"COPD": "COPD (फेफड़ों की पुरानी बीमारी)",
"Diabetes (Type 1)": "डायबिटीज़ (टाइप 1)",
"Diabetes (Type 2)": "डायबिटीज़ (टाइप 2)",
"Type 2 diabetes": "टाइप 2 डायबिटीज़",
"Type 1 diabetes": "टाइप 1 डायबिटीज़",
"Hypertension": "उच्च रक्तचाप",
"Heart disease": "दिल की बीमारी",
