"A lipid profile helps estimate heart risk.": "लिपिड प्रोफ़ाइल से दिल के जोखिम का अनुमान लगाने में मदद मिलती है।",
"A thyroid condition is monitored with TSH, usually every 6–12 months.": "थायरॉइड की स्थिति पर TSH से नज़र रखी जाती है, आमतौर पर हर 6–12 महीने में।",
"Blood pressure and diabetes both affect the kidneys; creatinine/eGFR is a routine yearly check.": "ब्लड प्रेशर और डायबिटीज़ दोनों गुर्दों पर असर डालते हैं; क्रिएटिनिन/eGFR की साल में एक बार नियमित जाँच होती है।",
"With diabetes on your profile, an HbA1c every 3–6 months is the standard way to track control.": "प्रोफ़ाइल में डायबिटीज़ होने पर, नियंत्रण पर नज़र रखने का मानक तरीक़ा हर 3–6 महीने में HbA1c जाँच है।",
"Read from the written reports, not the scan images. Always check against the original.": "यह लिखित रिपोर्टों से पढ़ा गया है, स्कैन की तस्वीरों से नहीं। हमेशा मूल रिपोर्ट से मिलान करें।",
"This is medication context, not an interaction checker or prescribing recommendation. Review changes with a clinician.": "यह दवाओं की जानकारी का संदर्भ है, दवाओं के आपसी असर की जाँच या दवा लिखने की सिफ़ारिश नहीं। कोई भी बदलाव डॉक्टर के साथ तय करें।",
"No CuraVault patient record is bound to this signed-in user.": "इस साइन-इन उपयोगकर्ता से कोई CuraVault मरीज़ रिकॉर्ड जुड़ा नहीं है।",
"Please check the details you entered.": "आपने जो जानकारी भरी है उसे कृपया जाँच लें।",
"We're getting a lot of sign-ups right now. Please try again": "अभी बहुत सारे साइन-अप आ रहे हैं। कृपया दोबारा कोशिश करें",
"Too many sign-up attempts from your network. Please try again": "आपके नेटवर्क से बहुत ज़्यादा साइन-अप कोशिशें हुईं। कृपया दोबारा कोशिश करें",
"Account created successfully.": "खाता सफलतापूर्वक बन गया।",
