"Doing okay, could use some care": "ठीक है, थोड़ी देखभाल की ज़रूरत है",
"Needs some extra love this week": "इस हफ़्ते थोड़ा ज़्यादा प्यार चाहिए",
"At birth": "जन्म पर",
