"Yearly growth check (height, weight) and a vision check before school age.": "हर साल बढ़त की जाँच (क़द, वज़न) और स्कूल की उम्र से पहले नज़र की जाँच।",
"A dental check every 6 months.": "हर 6 महीने में दाँतों की जाँच।",
"Blood pressure check at least once a year.": "साल में कम से कम एक बार ब्लड प्रेशर की जाँच।",
"A dental check every 6-12 months.": "हर 6-12 महीने में दाँतों की जाँच।",
"Blood sugar and cholesterol check every 1-3 years (sooner with family history).": "हर 1-3 साल में ब्लड शुगर और कोलेस्ट्रॉल की जाँच (परिवार में इतिहास हो तो और जल्दी)।",
"A yearly eye check (glaucoma and diabetes can be silent).": "साल में एक बार आँखों की जाँच (काला मोतिया और डायबिटीज़ चुपचाप हो सकते हैं)।",
"Talk to a gynaecologist about cervical screening.": "सर्वाइकल जाँच के बारे में स्त्री रोग विशेषज्ञ से बात करें।",
