"Ask your doctor about bowel (colorectal) screening.": "आँत (कोलोरेक्टल) जाँच के बारे में अपने डॉक्टर से पूछें।",
"Ask about yearly flu and pneumococcal vaccines, and a falls, hearing and vision review.": "सालाना फ़्लू और न्यूमोकोकल टीकों, और गिरने, सुनने व देखने की समीक्षा के बारे में पूछें।",
