"too many wrong PIN attempts": "PIN की बहुत ज़्यादा ग़लत कोशिशें",
"wrong PIN": "ग़लत PIN",
"Written by the patient in QueroCura. Symptom-check results are automated pattern matches from what the patient typed, not diagnoses.": "मरीज़ ने QueroCura में लिखा। लक्षण-जाँच के नतीजे मरीज़ के लिखे से स्वचालित पैटर्न मिलान हैं, निदान नहीं।",
"Only results the patient reviewed and confirmed are shown.": "सिर्फ़ वही नतीजे दिखाए गए हैं जिन्हें मरीज़ ने जाँचकर पक्का किया।",
"Vitals saved successfully.": "वाइटल्स सफलतापूर्वक सहेजे गए।",
"The top blood-pressure number should be larger than the bottom one.": "ब्लड प्रेशर की ऊपर वाली संख्या नीचे वाली से बड़ी होनी चाहिए।",
"Hypertensive crisis range — BP is 180/120 or higher.": "उच्च रक्तचाप के संकट का दायरा — BP 180/120 या उससे ज़्यादा है।",
"Elevated blood pressure — BP is 160/100 or higher.": "बढ़ा हुआ ब्लड प्रेशर — BP 160/100 या उससे ज़्यादा है।",
"Low blood pressure with fast pulse — possible shock/dehydration concern.": "कम ब्लड प्रेशर के साथ तेज़ नब्ज़ — शॉक/पानी की कमी की संभावना।",
"Very fast pulse — 130 bpm or higher.": "बहुत तेज़ नब्ज़ — 130 bpm या उससे ज़्यादा।",
"Fast pulse — 115 bpm or higher.": "तेज़ नब्ज़ — 115 bpm या उससे ज़्यादा।",
"Very slow pulse — 45 bpm or lower.": "बहुत धीमी नब्ज़ — 45 bpm या उससे कम।",
"Dangerously high fever — 40°C or higher.": "ख़तरनाक रूप से तेज़ बुख़ार — 40°C या उससे ज़्यादा।",
"High fever — 39°C or higher.": "तेज़ बुख़ार — 39°C या उससे ज़्यादा।",
"Low body temperature — 35.5°C or lower.": "शरीर का तापमान कम — 35.5°C या उससे कम।",
"Very high glucose reading. Medical advice is recommended urgently, especially with symptoms.": "ग्लूकोज़ की रीडिंग बहुत ऊँची। तुरंत डॉक्टरी सलाह लेने की सिफ़ारिश है, ख़ासकर लक्षण हों तो।",
"High glucose reading.": "ग्लूकोज़ की रीडिंग ऊँची।",
"Very low glucose reading. Treat as urgent, especially if shaky, confused, sweaty, or drowsy.": "ग्लूकोज़ की रीडिंग बहुत कम। इसे तुरंत ज़रूरी मानें, ख़ासकर कँपकँपी, भ्रम, पसीना या उनींदापन हो तो।",
"Low glucose reading.": "ग्लूकोज़ की रीडिंग कम।",
"See trends": "रुझान देखें",
"See why": "वजह देखें",
"Check in": "हाल-चाल दें",
"Finish your profile so every insight fits you better.": "अपनी प्रोफ़ाइल पूरी करें ताकि हर इनसाइट आपको बेहतर फ़िट बैठे।",
"Open profile": "प्रोफ़ाइल खोलें",
"No readings yet. A quick check-in would be lovely.": "अभी कोई रीडिंग नहीं। एक छोटा-सा हाल-चाल अच्छा रहेगा।",
