"Avg sugar": "औसत शुगर",
"This week's wins 🎉": "इस हफ़्ते की जीत 🎉",
"Your family 🫶": "आपका परिवार 🫶",
"Getting started": "शुरुआत करें",
"Log a first reading, upload a report to CuraVault, or run a symptom check. Your weekly story builds from there.": "पहली रीडिंग दर्ज करें, CuraVault में रिपोर्ट अपलोड करें, या लक्षण जाँच चलाएँ। आपकी साप्ताहिक कहानी वहीं से बनती है।",
"Open QueroCura": "QueroCura खोलें",
"Too many unusual requests. Please wait a few minutes.": "बहुत ज़्यादा असामान्य अनुरोध हुए। कृपया कुछ मिनट रुकें।",
