"For handwriting and scans: lay the page flat, keep the whole page in the frame, and shoot straight-on in daylight. After upload you'll check what was read before anything is saved.": "हाथ की लिखाई और स्कैन के लिए: पन्ना सपाट रखें, पूरा पन्ना फ़्रेम में रखें और दिन की रोशनी में सीधा खींचें। अपलोड के बाद, कुछ भी सहेजे जाने से पहले आप जाँच लेंगे कि क्या पढ़ा गया।",
