"Your file never leaves your device. Only readings from the last 13 months are sent, and duplicates are skipped so importing twice is safe.": "आपकी फ़ाइल आपके डिवाइस से बाहर नहीं जाती। सिर्फ़ पिछले 13 महीनों की रीडिंग भेजी जाती हैं, और दोहराव छोड़ दिए जाते हैं, इसलिए दो बार इम्पोर्ट करना सुरक्षित है।",
