"<b>✕ NO MATCH</b>No access granted. Nothing about the patient is exposed.": "<b>✕ मिलान नहीं</b>पहुँच नहीं दी गई। मरीज़ के बारे में कुछ भी उजागर नहीं होता।",
"<span>NEW</span>Send your doctor a one-page brief before your visit, with a QR code and PIN. <a>See how →</a>": "<span>नया</span>मुलाक़ात से पहले अपने डॉक्टर को QR कोड और PIN के साथ एक पन्ने का ब्योरा भेजें। <a>कैसे, देखें →</a>",
"A creeping blood pressure, a sudden weight drop, a condition that keeps coming back. Your readings are compared with your own history.": "धीरे-धीरे बढ़ता ब्लड प्रेशर, अचानक घटता वज़न, बार-बार लौटती कोई बीमारी। आपकी रीडिंग की तुलना आपके अपने इतिहास से होती है।",
"A few follow-up questions, each one chosen to rule something in or out, and it tells you why it asks.": "कुछ फ़ॉलो-अप सवाल, हर एक किसी संभावना को पक्का करने या हटाने के लिए चुना गया, और वह बताता है कि क्यों पूछ रहा है।",
"A gentle weekly story: what went well, what moved your score, and what is coming up.": "हर हफ़्ते की एक सहज कहानी: क्या अच्छा रहा, आपका स्कोर किससे बदला, और आगे क्या है।",
"A hospital sees nothing until you say yes, only what you pick, and only for as long as you allow.": "जब तक आप हाँ न कहें, अस्पताल कुछ नहीं देखता, सिर्फ़ वही जो आप चुनें, और सिर्फ़ तब तक जब तक आप अनुमति दें।",
"A link and QR code that need a PIN, expire on their own, and can be switched off any time.": "एक लिंक और QR कोड जिनके लिए PIN चाहिए, जो अपने आप समाप्त हो जाते हैं, और जिन्हें कभी भी बंद किया जा सकता है।",
