"Could it be my blood pressure? · Is my sleep making it worse?": "क्या यह मेरा ब्लड प्रेशर हो सकता है? · क्या मेरी नींद इसे बढ़ा रही है?",
"Cura asks what matters": "Cura वही पूछता है जो ज़रूरी है",
"Cura is listening": "Cura सुन रहा है",
"Cura understood": "Cura ने समझा",
"CuraVault reads your reports": "CuraVault आपकी रिपोर्ट पढ़ता है",
"Delete your account and everything in it yourself, from the Privacy page, whenever you choose.": "जब चाहें, गोपनीयता पेज से अपना खाता और उसमें सब कुछ ख़ुद हटाएँ।",
"Describe how you feel in your own words. QueroCura asks the follow-up questions a doctor would, tells you how urgent it is, keeps your reports and readings together, and gets you ready for your next visit.": "अपने शब्दों में बताइए कि आप कैसा महसूस कर रहे हैं। QueroCura वही फ़ॉलो-अप सवाल पूछता है जो एक डॉक्टर पूछता, बताता है कि मामला कितना ज़रूरी है, आपकी रिपोर्ट और रीडिंग एक साथ रखता है, और आपको अगली मुलाक़ात के लिए तैयार करता है।",
"Describe how you feel…": "बताइए आप कैसा महसूस कर रहे हैं…",
"Doctor brief": "डॉक्टर के लिए ब्योरा",
"Download everything we hold about you in one file, whenever you like.": "जब चाहें, हमारे पास आपके बारे में जो कुछ है, एक फ़ाइल में डाउनलोड करें।",
"Dr. Mehta, follow-up": "डॉ. मेहता, फ़ॉलो-अप",
"Each time anyone other than you opens your Vault, it is written to your access log, which you can read any time.": "जब भी आपके अलावा कोई आपका Vault खोलता है, वह आपके एक्सेस लॉग में दर्ज होता है, जिसे आप कभी भी पढ़ सकते हैं।",
"Encrypted records": "एन्क्रिप्टेड रिकॉर्ड",
"English & हिन्दी": "English और हिन्दी",
"Evening dose": "शाम की ख़ुराक",
"Every check, reading and report feeds one private record, so each part gets smarter because of the others.": "हर जाँच, रीडिंग और रिपोर्ट एक निजी रिकॉर्ड में जुड़ती है, इसलिए हर हिस्सा बाक़ी हिस्सों की वजह से और समझदार बनता है।",
"Every second before care starts is a second working against the patient. First responders often have no history at all.": "इलाज शुरू होने से पहले का हर सेकंड मरीज़ के ख़िलाफ़ जाता है। पहले पहुँचने वालों के पास अक्सर मरीज़ का कोई इतिहास नहीं होता।",
"Everything in CuraVault — emergency records, reports, prescriptions — is encrypted and accessible only through verification.": "CuraVault में सब कुछ — इमरजेंसी रिकॉर्ड, रिपोर्ट, पर्चे — एन्क्रिप्टेड है और सिर्फ़ पुष्टि के बाद ही खुलता है।",
"Everything your health needs, <span>working together.</span>": "आपकी सेहत की हर ज़रूरत, <span>एक साथ काम करती हुई।</span>",
"FAQ": "अक्सर पूछे जाने वाले सवाल",
"Feel better about your health, starting today.": "आज से ही अपनी सेहत को लेकर बेहतर महसूस करें।",
