"For hospitals & clinics": "अस्पतालों और क्लिनिकों के लिए",
"Free to join": "जुड़ना मुफ़्त",
"From “I don't feel right” to a clear next step, in about two minutes.": "“तबीयत ठीक नहीं लग रही” से अगले साफ़ क़दम तक, लगभग दो मिनट में।",
"Go now if": "अभी जाएँ अगर",
