"Google Fit / CSV": "Google Fit / CSV",
"Have you noticed any rash, or bleeding from your gums or nose?": "क्या आपने कोई चकत्ते, या मसूड़ों या नाक से ख़ून देखा है?",
"HbA1c": "HbA1c",
"Headache behind the eyes": "आँखों के पीछे सिरदर्द",
