"Health calendar": "स्वास्थ्य कैलेंडर",
"How a check works": "जाँच कैसे काम करती है",
"How a symptom check works": "लक्षण जाँच कैसे काम करती है",
"How it works": "यह कैसे काम करता है",
"How urgent it is, what is safe at home, what to avoid, and when to see a doctor.": "यह कितना ज़रूरी है, घर पर क्या सुरक्षित है, किससे बचें, और डॉक्टर को कब दिखाएँ।",
"Import blood pressure, glucose, SpO₂, weight, steps and sleep from Apple Health, Google or a spreadsheet. The file is read on your device, and only the numbers that matter are sent.": "Apple Health, Google या किसी स्प्रेडशीट से ब्लड प्रेशर, ग्लूकोज़, SpO₂, वज़न, क़दम और नींद इम्पोर्ट करें। फ़ाइल आपके डिवाइस पर ही पढ़ी जाती है, और सिर्फ़ ज़रूरी संख्याएँ भेजी जाती हैं।",
"In an emergency, your story arrives before the paperwork.": "इमरजेंसी में, आपकी कहानी काग़ज़ी कार्रवाई से पहले पहुँचती है।",
"In your own words": "आपके अपने शब्दों में",
"Insights that notice change": "बदलाव पहचानने वाले इनसाइट्स",
"Instead of a fixed checklist, Cura asks the next most useful question, the way a clinician narrows things down, and only shows a result once it is confident enough.": "तय चेकलिस्ट के बजाय, Cura अगला सबसे काम का सवाल पूछता है, जैसे कोई डॉक्टर संभावनाएँ कम करता है, और नतीजा तभी दिखाता है जब उसे पर्याप्त भरोसा हो।",
"Is QueroCura a doctor, or a diagnosis?": "क्या QueroCura डॉक्टर है, या निदान?",
"Know it was read": "पता चलता है कि पढ़ा गया",
"Know what to do next": "जानें कि आगे क्या करना है",
"Leave any time": "कभी भी छोड़ें",
"Links you control": "आपके नियंत्रण वाले लिंक",
"Look after parents and children from one account, and invite others to help.": "एक ही खाते से माता-पिता और बच्चों की देखभाल करें, और मदद के लिए दूसरों को बुलाएँ।",
