"No. A symptom check shows patterns that fit what you described, how urgent things look, and what is safe to do at home. It is a starting point for a conversation with your doctor, not a diagnosis, and it never tells you which medicine to take.": "नहीं। लक्षण जाँच वे पैटर्न दिखाती है जो आपके बताए से मेल खाते हैं, मामला कितना ज़रूरी लगता है, और घर पर क्या करना सुरक्षित है। यह आपके डॉक्टर से बातचीत की शुरुआत है, निदान नहीं, और यह कभी नहीं बताती कि कौन-सी दवा लें।",
"Nothing leaves your account unless you choose to share it, and you can see and undo every share.": "जब तक आप साझा करना न चुनें, कुछ भी आपके खाते से बाहर नहीं जाता, और आप हर साझा देख और वापस ले सकते हैं।",
