"cancelled an order": "ने एक ऑर्डर रद्द किया",
"wrote a shift handover about you": "ने आपके बारे में शिफ़्ट हैंडओवर लिखा",
"looked at your visit": "ने आपकी विज़िट देखी",
"AI help with my scans": "मेरे स्कैन में AI की मदद",
"Hospitals you connect to can ask an AI to prepare a draft read of your X-rays, CT, MRI and ultrasound images. Names and IDs are removed first, a doctor checks every finding and signs the report, and each AI read is listed below. Turn this off and they will read your scans without AI.": "जिन अस्पतालों से आप जुड़ते हैं, वे आपके एक्स-रे, सीटी, एमआरआई और अल्ट्रासाउंड की तस्वीरों को पढ़ने का शुरुआती मसौदा AI से बनवा सकते हैं। पहले नाम और पहचान हटा दी जाती है, डॉक्टर हर निष्कर्ष जाँचकर रिपोर्ट पर हस्ताक्षर करते हैं, और AI का हर उपयोग नीचे दिखता है। इसे बंद करें तो वे आपके स्कैन बिना AI के पढ़ेंगे।",
"Allow AI help with my scans": "मेरे स्कैन में AI की मदद की अनुमति दें",
"Hospitals may use AI to help read your scans.": "अस्पताल आपके स्कैन पढ़ने में AI की मदद ले सकते हैं।",
"Hospitals will read your scans without AI.": "अस्पताल आपके स्कैन बिना AI के पढ़ेंगे।",
"added a scan to your visit": "ने आपकी विज़िट में एक स्कैन जोड़ा",
"looked at your scan": "ने आपका स्कैन देखा",
"asked an AI to prepare a draft read of your scan": "ने आपके स्कैन का शुरुआती मसौदा AI से बनवाया",
"received an AI draft of your scan (not shown to you until a doctor signs)": "को आपके स्कैन का AI मसौदा मिला (डॉक्टर के हस्ताक्षर तक आपको नहीं दिखाया जाता)",
"signed your scan report": "ने आपकी स्कैन रिपोर्ट पर हस्ताक्षर किए",
"added a note to your scan report": "ने आपकी स्कैन रिपोर्ट में एक टिप्पणी जोड़ी",
"changed AI help with your scans": "ने अपने स्कैन में AI की मदद की सेटिंग बदली",
