"Link the QueroCura accounts of the people you love. Each person keeps their own account and records, and decides what you can see.": "जिन्हें आप प्यार करते हैं, उनके QueroCura खाते जोड़ें। हर व्यक्ति का अपना खाता और रिकॉर्ड रहता है, और वही तय करता है कि आप क्या देख सकते हैं।",
"Add a family member": "परिवार का सदस्य जोड़ें",
"Family members are linked QueroCura accounts. We send them a request; they accept in their own account and choose whether you can only see their health summary or also help add readings.": "परिवार के सदस्य जुड़े हुए QueroCura खाते होते हैं। हम उन्हें अनुरोध भेजते हैं; वे अपने खाते में स्वीकार करते हैं और चुनते हैं कि आप केवल उनका स्वास्थ्य सारांश देख सकें या रीडिंग जोड़ने में भी मदद कर सकें।",
