window.QC_HI_RX = [["^(\\d+) days?$", "$1 दिन"], ["^(\\d+) hours?$", "$1 घंटे"], ["^(\\d+) mins?$", "$1 मिनट"], ["^(\\d+) minutes?$", "$1 मिनट"], ["^(\\d+) readings?$", "$1 रीडिंग"], ["^(\\d+) times?$", "$1 बार"], ["^(\\d+)d ago$", "$1 दिन पहले"], ["^(\\d+)h ago$", "$1 घंटे पहले"], ["^(\\d+)m ago$", "$1 मिनट पहले"], ["^(\\d+)mo ago$", "$1 महीने पहले"], ["^just now$", "अभी-अभी"], ["^yesterday$", "कल"], ["^checked (\\d+) days? ago$", "$1 दिन पहले जाँचा"], ["^checked recently$", "हाल में जाँचा"], ["^(\\d+) of (\\d+) prep items ready$", "$2 में से $1 तैयारी की चीज़ें तैयार"], ["^Next up · (.+)$", "अगला · $1"], ["^With (.+)$", "@1 के साथ"], ["^Welcome back, (.+)$", "वापसी पर स्वागत है, @1"], ["^Hi, (.+)$", "नमस्ते, @1"], ["^Step (\\d+) of (\\d+)$", "चरण $1 / $2"], ["^(\\d+)% match$", "$1% मिलान"], ["^(\\d+) documents?$", "$1 दस्तावेज़"], ["^(\\d+) records?$", "$1 रिकॉर्ड"], ["^Let's understand your (.+) properly$", "आइए आपके $1 को ठीक से समझें"], ["^Start · ~(\\d+) min$", "शुरू करें · ~$1 मिनट"], ["^Question (\\d+) of (\\d+)$", "सवाल $1 / $2"], ["^You selected: (.+)\\. Please call your local emergency number \\(112 in India\\) or go to the nearest emergency department now — don't wait for the analysis\\.$", "आपने चुना: $1। अपने इलाक़े का इमरजेंसी नंबर (भारत में 112) मिलाएँ या अभी सबसे नज़दीकी इमरजेंसी विभाग जाएँ, विश्लेषण का इंतज़ार न करें।"], ["^Urgency: (.+)$", "तात्कालिकता: $1"], ["^Triage level: (.+)$", "ट्राइएज स्तर: $1"], ["^Nice to meet you, (.+)!$", "आपसे मिलकर अच्छा लगा, @1!"], ["^Add a (.+) reading$", "$1 की रीडिंग जोड़ें"], ["^Copy all \\((\\d+)\\)$", "सब कॉपी करें ($1)"], ["^Please confirm your e-mail \\((.+)\\) so you can always recover your account\\.$", "कृपया अपना ई-मेल ($1) पक्का करें ताकि आप हमेशा अपना खाता वापस पा सकें।"], ["^Your week in health · (.+)$", "सेहत में आपका हफ़्ता · $1"], ["^Let's get your first week going, (.+)\\.$", "चलिए, आपका पहला हफ़्ता शुरू करें, @1।"], ["^· signed in (.+)$", "· साइन इन: $1"], ["^Opened (\\d+) times?, most recently (.+)$", "$1 बार खोला गया, सबसे हाल में $2"], ["^Works until (.+) · opens up to (\\d+) times\\.$", "$1 तक चलेगा · अधिकतम $2 बार खुल सकता है।"], ["^Last doctor visit: (.+)$", "डॉक्टर से पिछली मुलाक़ात: $1"], ["^(.+?) (asked for access|viewed your information|added a record|connected using your code|opened EMERGENCY access|accessed your Vault)$", "$1 $2"], ["^Stop reminders for (.+?)\\? Follow your clinician's instructions before changing treatment\\.$", "$1 के रिमाइंडर रोकें? इलाज में कोई भी बदलाव करने से पहले अपने डॉक्टर के निर्देश मानें।"], ["^Profile (\\d+)% complete\\. Adding <b>(.+?)<\\/b> would sharpen your health score and symptom checks\\.$", "प्रोफ़ाइल $1% पूरी। <b>$2</b> जोड़ने से आपका सेहत स्कोर और लक्षण जाँचें और सटीक होंगी।"], ["^You're all set, (.+?)!$", "सब तैयार है, @1!"], ["^Cura's read · last (\\d+) days$", "Cura का विश्लेषण · पिछले $1 दिन"], ["^See all (\\d+) findings →$", "सभी $1 बातें देखें →"], ["^(\\d+) readings?$", "$1 रीडिंग"], ["^Trend · clear$", "रुझान · स्पष्ट"], ["^Trend · possible$", "रुझान · संभावित"], ["^Changed (.+)$", "बदला @1"], ["^Draft reliability: (high|moderate|low)$", "ड्राफ़्ट की विश्वसनीयता: $1"], ["^(\\d+) ongoing$", "$1 जारी"], ["^(\\d+) signals?$", "$1 संकेत"], ["^· (low|moderate|high) confidence$", "· $1 विश्वसनीयता"], ["^\\(notice (.+)\\)$", "(सूचना $1)"], ["^(Chrome|Edge|Firefox|Safari|Opera|Brave|Samsung Internet|Browser|App|QueroCura app) on (Windows|macOS|Mac|Linux|Android|iOS|iPhone|iPad|ChromeOS|Unknown device)$", "$2 पर $1"], ["^Here's your week, (.+)\\.$", "@1, यह रहा आपका हफ़्ता।"], ["^(.+): closest match$", "$1: सबसे क़रीबी मिलान"], ["^(.*advice\\.) Prepared (.+?)\\.?$", "$1 तैयार किया गया: $2"], ["^(Provisional|Good|High) confidence · last (\\d+) days$", "$1 विश्वसनीयता · पिछले $2 दिन"], ["^Based on your last (\\d+) days\\. A wellness estimate, not a diagnosis — it starts at 100 and moves with your vitals, symptom checks, conditions and lifestyle\\.$", "आपके पिछले $1 दिनों पर आधारित। यह सेहत का अनुमान है, निदान नहीं — यह 100 से शुरू होता है और आपके वाइटल्स, लक्षण जाँचों, स्थितियों और जीवनशैली के साथ बदलता है।"], ["^(\\d+)× in symptom checks · last (.+)$", "लक्षण जाँचों में $1× · आख़िरी $2"], ["^(\\d+)× · (.+)$", "$1× · $2"], ["^None of your last (\\d+) symptom checks? came back urgent or emergency — a good sign\\.$", "आपकी पिछली $1 लक्षण जाँचों में से कोई भी तात्कालिक या आपातकालीन नहीं निकली — यह अच्छा संकेत है।"], ["^Recent symptom check suggested: (.+)$", "हाल की लक्षण जाँच ने सुझाया: $1"], ["^(\\d+) ongoing conditions? on your profile \\((.+)\\)$", "आपकी प्रोफ़ाइल में $1 जारी स्थितियाँ ($2)"], ["^(\\d+) past conditions? in your history$", "आपके इतिहास में $1 पुरानी स्थितियाँ"], ["^(\\d+) follow-up check-ins? said things got worse$", "$1 फ़ॉलो-अप जाँचों में हालत बिगड़ने की बात कही गई"], ["^Came up (\\d+) times in your symptom checks - worth raising with a doctor\\.$", "आपकी लक्षण जाँचों में $1 बार सामने आया — डॉक्टर से चर्चा करने लायक़।"], ["^(\\d+) urgent symptom checks? recently$", "हाल में $1 तात्कालिक लक्षण जाँचें"], ["^(\\d+) critical lab results? in CuraVault$", "CuraVault में $1 गंभीर लैब नतीजे"], ["^(\\d+) lab markers? outside the usual range$", "$1 लैब मार्कर सामान्य दायरे से बाहर"], ["^(\\d+) borderline lab markers?$", "$1 सीमा-रेखा वाले लैब मार्कर"], ["^(\\d+) imaging reports? with findings to review$", "$1 इमेजिंग रिपोर्ट जिनके निष्कर्ष देखने लायक़ हैं"], ["^(.+) has been (rising|falling) lately$", "$1 हाल में $2 दिख रहा है"], ["^You've also logged (\\d+) symptom checks? in the same (\\d+)-day window — worth mentioning both together at your next check-up\\.$", "आपने उसी $2 दिन की अवधि में $1 लक्षण जाँच भी दर्ज की है — अगली जाँच में दोनों का साथ ज़िक्र करना ठीक रहेगा।"], ["^(.+) keeps coming up$", "$1 बार-बार सामने आ रहा है"], ["^(.+) flagged as urgent$", "$1 तात्कालिक चिह्नित"], ["^Logged (\\d+) times in the last (\\d+) days, most recently on (.+)\\. A recurring pattern like this is worth flagging to a doctor\\.$", "पिछले $2 दिनों में $1 बार दर्ज हुआ, सबसे हाल में $3 को। इस तरह का दोहराव वाला पैटर्न डॉक्टर को बताने लायक़ है।"], ["^(.+) has come up (\\d+) times$", "$1 $2 बार सामने आया"], ["^How is your (.+) now\\?$", "आपका $1 अब कैसा है?"], ["^Get (.+) checked soon$", "$1 की जाँच जल्द कराएँ"], ["^Keep a closer eye on (.+)$", "$1 पर नज़दीकी नज़र रखें"], ["^(\\d+) of your recent symptom checks came back urgent or emergency\\.$", "आपकी हाल की $1 लक्षण जाँचें तात्कालिक या आपातकालीन निकलीं।"], ["^Bring up (.+) at your next visit$", "अगली मुलाक़ात में $1 की चर्चा करें"], ["^It's come up (\\d+) times in your symptom checks — worth a proper look\\.$", "आपकी लक्षण जाँचों में यह $1 बार सामने आया है — इसे ठीक से दिखाना चाहिए।"], ["^No (.+) readings yet$", "अभी कोई $1 रीडिंग नहीं"], ["^Log a (.+) reading to unlock its trend chart\\.$", "$1 की रीडिंग दर्ज करें ताकि उसका ट्रेंड चार्ट खुल सके।"], ["^(\\d+) urgent-or-worse signal\\(s\\) in the last (\\d+) days\\. Including (\\d+) follow-up check-ins? that said things got worse\\.$", "पिछले $2 दिनों में $1 तात्कालिक-या-गंभीर संकेत। इनमें $3 फ़ॉलो-अप जाँचें शामिल हैं जिनमें हालत बिगड़ने की बात कही गई।"], ["^Symptom checks flagged urgent or emergency: (\\d+) \\(closest patterns: (.+)\\)\\.$", "तात्कालिक या आपातकालीन चिह्नित लक्षण जाँचें: $1 (सबसे क़रीबी पैटर्न: $2)।"], ["^Symptom checks logged: (\\d+); most recent pattern: (.+)\\.$", "दर्ज लक्षण जाँचें: $1; सबसे हाल का पैटर्न: $2।"], ["^Lab values outside the usual range: (.+)\\.$", "सामान्य दायरे से बाहर लैब मान: $1।"], ["^Alert raised in the app: (.+)\\.$", "ऐप में उठाया गया अलर्ट: $1।"], ["^(.+) \\((low|high)\\)$", "$1 ($2)"], ["^(.+): latest (.+?) (°C|%|bpm|mmHg|mg/dL|kg), (going up|going down) over (\\d+) readings \\(range (.+) to (.+)\\)\\.$", "$1: ताज़ा $2 $3, $4 — $5 रीडिंग में (दायरा $6 से $7)।"], ["^(.+): latest (.+?) (°C|%|bpm|mmHg|mg/dL|kg) over (\\d+) readings \\(range (.+) to (.+)\\)\\.$", "$1: ताज़ा $2 $3 — $4 रीडिंग में (दायरा $5 से $6)।"], ["^(.+): latest (.+?) (°C|%|bpm|mmHg|mg/dL|kg), (going up|going down)\\.$", "$1: ताज़ा $2 $3, $4।"], ["^(.+): latest (.+?) (°C|%|bpm|mmHg|mg/dL|kg)\\.$", "$1: ताज़ा $2 $3।"], ["^My blood pressure has been running (.+)\\. What is my target, do I need tests \\(kidney, heart, eyes\\), and how often should I check it at home\\?$", "मेरा ब्लड प्रेशर $1 चल रहा है। मेरा लक्ष्य क्या है, क्या मुझे जाँचें (गुर्दे, दिल, आँखें) करानी चाहिए, और घर पर कितनी बार मापना चाहिए?"], ["^My blood sugar readings have been flagged as (.+)\\. Do I need an HbA1c or other test, and what range should I aim for\\?$", "मेरी ब्लड शुगर की रीडिंग को $1 चिह्नित किया गया है। क्या मुझे HbA1c या कोई और जाँच करानी चाहिए, और मेरा लक्ष्य दायरा क्या हो?"], ["^My oxygen saturation readings have been flagged as (.+)\\. Does this need a chest check or lung test, and what level means I should seek help\\?$", "मेरी ऑक्सीजन सैचुरेशन की रीडिंग को $1 चिह्नित किया गया है। क्या इसके लिए छाती की जाँच या फेफड़ों का टेस्ट चाहिए, और किस स्तर पर मुझे मदद लेनी चाहिए?"], ["^My pulse has been flagged as (.+)\\. Do I need an ECG or heart rhythm test, and when should I worry\\?$", "मेरी नब्ज़ को $1 चिह्नित किया गया है। क्या मुझे ECG या दिल की धड़कन की लय की जाँच चाहिए, और मुझे कब चिंता करनी चाहिए?"], ["^I have had temperatures flagged as (.+)\\. What is the cause likely to be, and which tests should I have if it keeps coming back\\?$", "मेरे तापमान को $1 चिह्नित किया गया है। इसकी संभावित वजह क्या है, और अगर यह बार-बार लौटे तो कौन-सी जाँचें करानी चाहिए?"], ["^(.+) has come up (\\d+) times in my symptom checks\\. Is something ongoing behind it, and which test would confirm or rule it out\\?$", "मेरी लक्षण जाँचों में $1 $2 बार सामने आया है। क्या इसके पीछे कुछ लगातार चल रहा है, और कौन-सी जाँच इसकी पुष्टि करेगी या इसे ख़ारिज करेगी?"], ["^I had (\\d+) symptom checks? flagged as urgent \\((.+)\\)\\. Do I need follow-up tests, and what should I do if it happens again\\?$", "मेरी $1 लक्षण जाँच तात्कालिक चिह्नित हुई ($2)। क्या मुझे फ़ॉलो-अप जाँचें करानी चाहिए, और दोबारा ऐसा हो तो मुझे क्या करना चाहिए?"], ["^I had (\\d+) symptom checks? flagged as urgent\\. Do I need follow-up tests, and what should I do if it happens again\\?$", "मेरी $1 लक्षण जाँच तात्कालिक चिह्नित हुई। क्या मुझे फ़ॉलो-अप जाँचें करानी चाहिए, और दोबारा ऐसा हो तो मुझे क्या करना चाहिए?"], ["^My latest symptom check pointed to (.+)\\. Does that fit what you find, and what else could it be\\?$", "मेरी ताज़ा लक्षण जाँच में $1 का संकेत मिला। क्या यह आपकी जाँच से मेल खाता है, और इसके अलावा और क्या हो सकता है?"], ["^Given my (.+), which readings or symptoms should I track between visits, and when should I contact you\\?$", "मेरी $1 को देखते हुए, मुलाक़ातों के बीच मुझे कौन-सी रीडिंग या लक्षण दर्ज करने चाहिए, और आपसे कब संपर्क करना चाहिए?"], ["^(.+) has come up (\\d+) times recently — is this something ongoing I should be managing differently\\?$", "$1 हाल में $2 बार सामने आया है — क्या यह कुछ ऐसा है जो चल रहा है और जिसे मुझे अलग तरह से संभालना चाहिए?"], ["^My (.+) has been flagged as (.+) lately — should I be concerned, and is there anything I should change before my next visit\\?$", "मेरा $1 हाल में $2 चिह्नित हुआ है — क्या मुझे चिंता करनी चाहिए, और अगली मुलाक़ात से पहले मुझे कुछ बदलना चाहिए?"], ["^I had (\\d+) symptom checks? flagged urgent recently \\(around (.+)\\) — do I need any follow-up testing\\?$", "हाल में मेरी $1 लक्षण जाँच तात्कालिक चिह्नित हुई ($2 के आसपास) — क्या मुझे कोई फ़ॉलो-अप जाँच करानी चाहिए?"], ["^I had (\\d+) symptom checks? flagged urgent recently — do I need any follow-up testing\\?$", "हाल में मेरी $1 लक्षण जाँच तात्कालिक चिह्नित हुई — क्या मुझे कोई फ़ॉलो-अप जाँच करानी चाहिए?"], ["^Given my (.+), are there specific vitals or symptoms I should be tracking between visits\\?$", "मेरी $1 को देखते हुए, क्या कुछ ख़ास वाइटल्स या लक्षण हैं जिन पर मुझे मुलाक़ातों के बीच नज़र रखनी चाहिए?"], ["^My results show this pattern: (.+)\\. What could be causing it, and which tests or changes should come next\\?$", "मेरे नतीजों में यह पैटर्न दिख रहा है: $1। इसकी वजह क्या हो सकती है, और आगे कौन-सी जाँचें या बदलाव होने चाहिए?"], ["^My (.+) was (low|high) \\((.+)\\)\\. What could explain that, and when should I re-test\\?(?: (.+))?$", "मेरा $1 $2 था ($3)। इसकी क्या वजह हो सकती है, और मुझे दोबारा जाँच कब करानी चाहिए? $4"], ["^My latest (.+) report says the (.+) is (.+) mm, up from (.+) mm\\. Does this need action, and what is the follow-up plan\\?$", "मेरी ताज़ा $1 रिपोर्ट के अनुसार $2 $3 मिमी है, जो पहले $4 मिमी था। क्या इस पर कार्रवाई चाहिए, और फ़ॉलो-अप की योजना क्या है?"], ["^My (.+) report mentions (.+)\\. What does it mean for me, and do I need further tests or a specialist\\?$", "मेरी $1 रिपोर्ट में $2 का ज़िक्र है। मेरे लिए इसका क्या मतलब है, और क्या मुझे और जाँचें या किसी विशेषज्ञ की ज़रूरत है?"], ["^(\\d+) urgent-or-worse signal\\(s\\) in the last (\\d+) days\\.$", "पिछले $2 दिनों में $1 तात्कालिक-या-गंभीर संकेत।"], ["^(.+) appears above a common reference threshold$", "$1 सामान्य संदर्भ सीमा से ऊपर दिखता है"], ["^(.+) appears below a common reference threshold$", "$1 सामान्य संदर्भ सीमा से नीचे दिखता है"], ["^(.+) found$", "$1 मिला"], ["^(\\d+) vital reading\\(s\\) were recorded\\.$", "$1 वाइटल रीडिंग दर्ज हुईं।"], ["^(\\d+) blood-report-like upload\\(s\\) were found\\.$", "$1 ब्लड-रिपोर्ट जैसे अपलोड मिले।"], ["^Extracted (\\d+) lab marker\\(s\\)\\.$", "$1 लैब मार्कर निकाले गए।"], ["^(\\d+) item\\(s\\) may need context or follow-up\\.$", "$1 चीज़ों को संदर्भ या फ़ॉलो-अप की ज़रूरत हो सकती है।"], ["^Detected health themes: (.+)\\.$", "पहचाने गए सेहत के विषय: $1।"], ["^In (.+), CuraVault found (\\d+) month\\(s\\) with blood-report activity, (\\d+) extracted marker\\(s\\), and (\\d+) item\\(s\\) needing context\\.$", "$1 में CuraVault को ब्लड-रिपोर्ट गतिविधि वाले $2 महीने, $3 निकाले गए मार्कर और संदर्भ चाहने वाली $4 चीज़ें मिलीं।"], ["^All (\\d+) confirmed lab markers are within range\\.$", "सभी $1 पुष्ट लैब मार्कर दायरे के भीतर हैं।"], ["^(\\d+) of (\\d+) confirmed lab markers are outside the usual range\\.$", "$2 में से $1 पुष्ट लैब मार्कर सामान्य दायरे से बाहर हैं।"], ["^Calculated from your creatinine, age and sex \\(CKD-EPI 2021\\)\\. Stage (.+)\\. Needs 3\\+ months of results to classify kidney disease\\.$", "आपके क्रिएटिनिन, उम्र और लिंग से गणना की गई (CKD-EPI 2021)। चरण $1। गुर्दे की बीमारी का वर्गीकरण करने के लिए 3+ महीनों के नतीजे चाहिए।"], ["^HbA1c is (in the diabetes range|in the prediabetes range)$", "HbA1c $1 है"], ["^(.+) \\((.+) since (.+)\\)$", "$1 ($3 से $2)"], ["^above (.+)$", "$1 से ऊपर"], ["^The radiologist recommends follow-up within about (\\d+) months?\\(s\\)\\.?$", "रेडियोलॉजिस्ट लगभग $1 महीने में फ़ॉलो-अप की सलाह देते हैं"], ["^The radiologist recommends follow-up within about (\\d+) months?\\.?$", "रेडियोलॉजिस्ट लगभग $1 महीने में फ़ॉलो-अप की सलाह देते हैं"], ["^Ejection fraction (.+)% — normal$", "इजेक्शन फ़्रैक्शन $1% — सामान्य"], ["^Ejection fraction (.+)% — low-normal$", "इजेक्शन फ़्रैक्शन $1% — सामान्य का निचला सिरा"], ["^Ejection fraction (.+)% — mildly reduced$", "इजेक्शन फ़्रैक्शन $1% — हल्का घटा हुआ"], ["^Ejection fraction (.+)% — reduced$", "इजेक्शन फ़्रैक्शन $1% — घटा हुआ"], ["^T-score (.+) — normal$", "T-स्कोर $1 — सामान्य"], ["^T-score (.+) — low bone density \\(osteopenia\\)$", "T-स्कोर $1 — कम हड्डी घनत्व (ऑस्टियोपीनिया)"], ["^T-score (.+) — osteoporosis range$", "T-स्कोर $1 — ऑस्टियोपोरोसिस का दायरा"], ["^Calcium score (.+) — (mild|moderate|extensive)$", "कैल्शियम स्कोर $1 — $2"], ["^Common bile duct (.+) mm — (dilated|normal)$", "कॉमन बाइल डक्ट $1 mm — $2"], ["^Prostate volume (.+) mL — (.+)$", "प्रोस्टेट का आयतन $1 mL — $2"], ["^Cardiothoracic ratio (.+) — (enlarged|normal)$", "कार्डियोथोरेसिक अनुपात $1 — $2"], ["^This (.+?) report of the (.+?) reads as normal, with no significant abnormality described\\.$", "यह $2 की $1 रिपोर्ट सामान्य पढ़ी जाती है, इसमें कोई उल्लेखनीय असामान्यता नहीं बताई गई।"], ["^This (.+?) report reads as normal, with no significant abnormality described\\.$", "यह $1 रिपोर्ट सामान्य पढ़ी जाती है, इसमें कोई उल्लेखनीय असामान्यता नहीं बताई गई।"], ["^This (.+?) report of the (.+?) mentions only minor or age-related findings: ([^.]+)\\.$", "यह $2 की $1 रिपोर्ट सिर्फ़ मामूली या उम्र से जुड़े निष्कर्षों का ज़िक्र करती है: $3।"], ["^This (.+?) report mentions only minor or age-related findings: ([^.]+)\\.$", "यह $1 रिपोर्ट सिर्फ़ मामूली या उम्र से जुड़े निष्कर्षों का ज़िक्र करती है: $2।"], ["^This (.+?) report of the (.+?) describes: ([^.]+)\\.$", "यह $2 की $1 रिपोर्ट बताती है: $3।"], ["^This (.+?) report describes: ([^.]+)\\.$", "यह $1 रिपोर्ट बताती है: $2।"], ["^This (.+?) report of the (.+?) could not be summarised reliably\\.$", "इस $2 की $1 रिपोर्ट का भरोसेमंद सारांश नहीं बन सका।"], ["^This (.+?) report could not be summarised reliably\\.$", "इस $1 रिपोर्ट का भरोसेमंद सारांश नहीं बन सका।"], ["^Stated grade or measurement: ([^.]+)\\.$", "बताया गया ग्रेड या माप: $1।"], ["^The radiologist recommends follow-up within about (\\d+) month\\(s\\): ([^.]+)\\.$", "रेडियोलॉजिस्ट लगभग $1 महीने में फ़ॉलो-अप की सलाह देते हैं: $2।"], ["^The radiologist recommends follow-up: ([^.]+)\\.$", "रेडियोलॉजिस्ट फ़ॉलो-अप की सलाह देते हैं: $1।"], ["^(BI-RADS|Bosniak|Fazekas|LI-RADS|PI-RADS|TI-RADS|Lung-RADS) (.+?) — (.+)$", "$1 $2 — $3"], ["^Kellgren–Lawrence (.+?) — (.+)$", "केलग्रेन–लॉरेंस $1 — $2"], ["^Critical result: (.+)$", "गंभीर नतीजा: $1"], ["^Discuss (.+)$", "$1 पर चर्चा करें"], ["^Review (.+)$", "$1 की समीक्षा करें"], ["^Repeat (.+)$", "$1 दोहराएँ"], ["^Ask whether the (.+) pattern needs repeat checks, medication review, or correlation with symptoms\\.$", "पूछें कि क्या $1 पैटर्न के लिए दोबारा जाँच, दवा की समीक्षा या लक्षणों से मिलान चाहिए।"], ["^(.+) appears elevated\\. Liver, muscle, medication and alcohol context may matter\\.$", "$1 ऊँचा दिखता है। जिगर, मांसपेशियों, दवाओं और शराब का संदर्भ मायने रख सकता है।"], ["^(.+) is not obviously elevated from this broad rule\\.$", "इस व्यापक नियम से $1 साफ़ तौर पर ऊँचा नहीं है।"], ["^(.+) was detected from a report\\. Interpretation improves with reference range, units and trend\\.$", "$1 रिपोर्ट से पहचाना गया। संदर्भ दायरे, इकाई और रुझान के साथ व्याख्या बेहतर होती है।"], ["^(.+) has urgent-level signals that should be reviewed promptly\\.$", "$1 में तात्कालिक स्तर के संकेत हैं जिनकी तुरंत समीक्षा होनी चाहिए।"], ["^(.+) has (\\d+) marker\\(s\\) worth watching or discussing\\.$", "$1 में $2 मार्कर हैं जिन पर नज़र रखना या चर्चा करना उपयोगी है।"], ["^(.+) has structured markers without obvious broad-rule warning signals\\.$", "$1 में व्यवस्थित मार्कर हैं जिनमें व्यापक नियम के कोई साफ़ चेतावनी संकेत नहीं हैं।"], ["^(.+) has no structured markers yet\\.$", "$1 में अभी कोई व्यवस्थित मार्कर नहीं हैं।"], ["^CuraVault found (\\d+) urgent signal\\(s\\) needing prompt clinical review\\.$", "CuraVault को $1 तात्कालिक संकेत मिले जिनकी तुरंत चिकित्सकीय समीक्षा चाहिए।"], ["^CuraVault found (\\d+) watchpoint\\(s\\) worth discussing or tracking\\.$", "CuraVault को $1 ऐसे बिंदु मिले जिन पर चर्चा या नज़र रखना उपयोगी है।"], ["^(.+) has no strong structured signal yet because relevant data is missing or limited\\.$", "$1 में अभी कोई मज़बूत व्यवस्थित संकेत नहीं है, क्योंकि संबंधित डेटा नहीं है या सीमित है।"], ["^(.+) has only indirect supporting signals\\. A primary marker is needed before calling this a system-level watch area\\.$", "$1 में सिर्फ़ अप्रत्यक्ष सहायक संकेत हैं। इसे प्रणाली-स्तर का निगरानी क्षेत्र कहने से पहले एक प्राथमिक मार्कर चाहिए।"], ["^(.+) has urgent-level primary signal\\(s\\)\\. This should be reviewed promptly in clinical context\\.$", "$1 में तात्कालिक स्तर के प्राथमिक संकेत हैं। इनकी चिकित्सकीय संदर्भ में तुरंत समीक्षा होनी चाहिए।"], ["^(.+) has primary pattern\\(s\\) worth watching, especially if repeated or linked with symptoms\\.$", "$1 में ऐसे प्राथमिक पैटर्न हैं जिन पर नज़र रखना उपयोगी है, ख़ासकर अगर वे दोहराए जाएँ या लक्षणों से जुड़े हों।"], ["^(.+) does not show an obvious broad-rule warning pattern from available data\\.$", "उपलब्ध डेटा से $1 में व्यापक नियम का कोई साफ़ चेतावनी पैटर्न नहीं दिखता।"], ["^(\\d+) body-system area\\(s\\) need prompt clinical review\\.$", "$1 शरीर-प्रणाली क्षेत्रों की तुरंत चिकित्सकीय समीक्षा चाहिए।"], ["^(\\d+) body-system area\\(s\\) worth watching\\.$", "$1 शरीर-प्रणाली क्षेत्र निगरानी लायक़ हैं।"], ["^(\\d+) cross-signal pattern\\(s\\) worth reviewing\\.$", "$1 क्रॉस-सिग्नल पैटर्न समीक्षा लायक़ हैं।"], ["^(\\d+) watchpoint\\(s\\) found in available data\\.$", "उपलब्ध डेटा में $1 निगरानी बिंदु मिले।"], ["^(.+) Ask whether this needs repeat testing, symptom correlation, or monitoring\\.$", "$1 पूछें कि क्या इसकी दोबारा जाँच, लक्षणों से मिलान या निगरानी चाहिए।"], ["^(\\d+) reading\\(s\\)$", "$1 रीडिंग"], ["^(.+): (.+); status (.+); panel (.+)\\.$", "$1: $2; स्थिति $3; पैनल $4।"], ["^(.+) has (\\d+) primary signal\\(s\\), so it is a stronger reasoning area\\.$", "$1 में $2 प्राथमिक संकेत हैं, इसलिए यह विश्लेषण का ज़्यादा मज़बूत क्षेत्र है।"], ["^(.+) has supporting signals but lacks primary evidence\\.$", "$1 में सहायक संकेत हैं पर प्राथमिक प्रमाण नहीं हैं।"], ["^(.+) needs more direct data before CuraSense should reason strongly about it\\.$", "CuraSense इस पर मज़बूती से विश्लेषण करे, इससे पहले $1 के लिए और सीधा डेटा चाहिए।"], ["^(.+) changed by (.+) across (\\d+) readings\\.$", "$1 $3 रीडिंग में $2 बदला।"], ["^Pulse changed by (.+) across (\\d+) readings\\.$", "नब्ज़ $2 रीडिंग में $1 बदली।"], ["^SpO₂ fell by (.+) percentage point\\(s\\)\\.$", "SpO₂ $1 प्रतिशत अंक गिरा।"], ["^Temperature reached (.+), which can fit fever context\\.$", "तापमान $1 तक पहुँचा, जो बुख़ार के संदर्भ से मेल खा सकता है।"], ["^(.+) changed by about (.+)% across available readings\\.$", "उपलब्ध रीडिंग में $1 लगभग $2% बदला।"], ["^(.+) trend change$", "$1 के रुझान में बदलाव"], ["^CuraSense found watch areas around (.+)\\. These are not diagnoses, but they are useful areas to discuss or track\\.$", "CuraSense को $1 के आसपास निगरानी क्षेत्र मिले। ये निदान नहीं हैं, पर चर्चा करने या नज़र रखने के उपयोगी क्षेत्र हैं।"], ["^Discuss (.+) with a clinician if this matches symptoms or repeats\\.$", "अगर यह लक्षणों से मेल खाता है या दोहराता है तो $1 पर डॉक्टर से चर्चा करें।"], ["^Invalid medicine (.+)\\.?$", "अमान्य दवा @1।"], ["^in about (\\d+) minute(?:s?)$", "लगभग $1 मिनट में"], ["^Too many sign-in attempts\\. Please wait (\\d+) minute(?:s?) and try again, or reset your password\\.$", "साइन-इन की बहुत ज़्यादा कोशिशें हुईं। कृपया $1 मिनट रुककर दोबारा कोशिश करें, या अपना पासवर्ड रीसेट करें।"], ["^You can look after up to (\\d+) people from one account\\.$", "आप एक खाते से अधिकतम $1 लोगों की देखभाल कर सकते हैं।"], ["^Welcome to the family, (.+?)!$", "परिवार में आपका स्वागत है, @1!"], ["^(.+?)'s profile and everything in it has been deleted\\.$", "$1 की प्रोफ़ाइल और उसमें सब कुछ हटा दिया गया है।"], ["^A care circle can have up to (\\d+) people\\.$", "एक केयर सर्कल में अधिकतम $1 लोग हो सकते हैं।"], ["^Invite saved\\. They'll see it when they sign in to QueroCura with (.+?)\\.$", "न्योता सहेज लिया गया। जब वे $1 से QueroCura में साइन इन करेंगे तो उन्हें दिखेगा।"], ["^Sent (.+?) to (.+?)$", "$2 को $1 भेजा गया"], ["^You have (\\d+) active links\\. Please remove one first\\.$", "आपके $1 लिंक चालू हैं। कृपया पहले एक हटाएँ।"], ["^That (.+?) value doesn't look right\\. Please check it\\.$", "वह $1 का मान सही नहीं लगता। कृपया जाँच लें।"], ["^Very low oxygen level — SpO₂ below 92%\\. Seek urgent medical care\\.$", "ऑक्सीजन का स्तर बहुत कम — SpO₂ 92% से नीचे। तुरंत चिकित्सा सहायता लें।"], ["^Low oxygen level — SpO₂ between 92–94%\\.$", "ऑक्सीजन का स्तर कम — SpO₂ 92–94% के बीच।"], ["^You logged your vitals on (\\d+) of 7 days\\. That kind of consistency is what makes trends meaningful\\.$", "आपने 7 में से $1 दिन वाइटल्स दर्ज किए। यही निरंतरता रुझानों को सार्थक बनाती है।"], ["^You logged vitals on (\\d+) day(?:s?) this week\\. Every reading helps\\.$", "आपने इस हफ़्ते $1 दिन वाइटल्स दर्ज किए। हर रीडिंग मदद करती है।"], ["^Your blood pressure averaged (\\d+)\\/(\\d+) this week, comfortably in the usual range\\.$", "इस हफ़्ते आपका ब्लड प्रेशर औसतन $1/$2 रहा, जो आराम से सामान्य दायरे में है।"], ["^You told us (.+?) cleared up\\. We're glad you're feeling better\\.$", "आपने बताया कि $1 ठीक हो गया। हमें ख़ुशी है कि आप बेहतर महसूस कर रहे हैं।"], ["^Your health score is up (\\d+) points from last week\\.$", "आपका सेहत स्कोर पिछले हफ़्ते से $1 अंक बढ़ा है।"], ["^You averaged about (.+?) steps a day\\. Your body will thank you\\.$", "आपने रोज़ औसतन लगभग $1 क़दम चले। आपका शरीर आपका शुक्रिया करेगा।"], ["^Your sleep averaged ([\\d.]+) hours, right where most adults do best\\.$", "आपकी नींद औसतन $1 घंटे रही, जो ज़्यादातर वयस्कों के लिए सबसे अच्छी है।"], ["^Your blood pressure averaged (\\d+)\\/(\\d+), a little high\\. If this keeps up, mention it to your doctor\\.$", "आपका ब्लड प्रेशर औसतन $1/$2 रहा, थोड़ा ऊँचा। अगर यह बना रहे तो अपने डॉक्टर को बताएँ।"], ["^Your health score dipped (\\d+) points\\. Insights shows what moved it\\.$", "आपका सेहत स्कोर $1 अंक गिरा। इनसाइट्स में दिखता है कि क्या बदला।"], ["^How is your (.+?) now\\? A quick check-in keeps your score honest\\.$", "आपका $1 अब कैसा है? एक छोटा-सा हाल-चाल आपके स्कोर को सटीक रखता है।"], ["^(\\d+) day(?:s?) of readings$", "$1 दिन की रीडिंग"], ["^A steady week, (.+?)\\.$", "एक स्थिर हफ़्ता, @1।"], ["^A great week, (.+?)\\.$", "शानदार हफ़्ता, @1।"], ["^(.+?)'s care circle$", "$1 का केयर सर्कल"], ["^(.+?)'s space$", "$1 की जगह"], ["^<b>How is this now\\?<\\/b> You checked this (.+?)\\. Are you feeling better\\?$", "<b>अब कैसा है?</b> आपने इसे $1 जाँचा था। क्या आप बेहतर महसूस कर रहे हैं?"], ["^This check is saved to <a>Insights → Ongoing conditions<\\/a>, so you can always see what's been flagged\\. In a day or two I'll ask how you're feeling, and once you say you're better it comes off your ongoing list\\. It's a possibility, not a diagnosis\\. Already living with <b>(.+?)<\\/b>\\? <a>Add it to my profile<\\/a>\\.$", "यह जाँच <a>इनसाइट्स → जारी बीमारियाँ</a> में सहेजी गई है, ताकि आप हमेशा देख सकें कि क्या चिह्नित हुआ। एक-दो दिन में मैं पूछूँगा कि आप कैसा महसूस कर रहे हैं, और आपके बेहतर बताने पर यह आपकी जारी सूची से हट जाएगी। यह एक संभावना है, निदान नहीं। क्या आप पहले से <b>$1</b> के साथ जी रहे हैं? <a>इसे मेरी प्रोफ़ाइल में जोड़ें</a>।"], ["^birthday in (\\d+)d$", "जन्मदिन में $1 दिन"], ["^(.+?) must be a number\\.$", "$1 एक संख्या होनी चाहिए।"], ["^(.+?) of (.+?) doesn't look right \\(expected (.+?)–(.+?)\\)\\.$", "$2 का $1 सही नहीं लगता (अपेक्षित $3–$4)।"], ["^That looks like °F — about (.+?) °C\\. Enter °C\\.$", "यह °F जैसा लगता है — लगभग $1 °C। °C में डालें।"], ["^That's a (\\d+)% jump — kg, not lb\\?$", "यह $1% की छलाँग है — kg में, lb नहीं?"], ["^ends in (\\d+) days$", "$1 दिन में समाप्त"], ["^ends in (\\d+) h$", "$1 घंटे में समाप्त"], ["^ends in (\\d+) min$", "$1 मिनट में समाप्त"], ["^Today, (.+?)$", "आज, $1"], ["^Tomorrow, (.+?)$", "कल, $1"], ["^(.+?) \\(about your (.+?) check\\)$", "$1 (आपकी $2 जाँच के बारे में)"], ["^couldn't read: (.+?)$", "पढ़ नहीं सके: $1"], ["^Delete \"(.+?)\"\\? This can't be undone\\.$", "\"$1\" हटाएँ? यह वापस नहीं हो सकता।"], ["^(.+?) days ago$", "$1 दिन पहले"], ["^You approved a request from (.+?)$", "आपने $1 का अनुरोध मंज़ूर किया"], ["^You declined a request from (.+?)$", "आपने $1 का अनुरोध अस्वीकार किया"], ["^You turned off access for (.+?)$", "आपने $1 की पहुँच बंद की"], ["^<b>(.+?)<\\/b> invited you to help look after <b>(.+?)<\\/b> \\(look & add\\)\\.$", "<b>$1</b> ने आपको <b>$2</b> की देखभाल में मदद के लिए बुलाया है (देखें और जोड़ें)।"], ["^<b>(.+?)<\\/b> invited you to help look after <b>(.+?)<\\/b> \\(look only\\)\\.$", "<b>$1</b> ने आपको <b>$2</b> की देखभाल में मदद के लिए बुलाया है (सिर्फ़ देखें)।"], ["^Looks like <span>(.+?)<\\/span>\\. I picked “(.+?)” for you; change it if that's wrong\\.$", "यह <span>$1</span> जैसा लगता है। मैंने आपके लिए “$2” चुना है; ग़लत हो तो बदल लें।"], ["^Smoking: (.+?) · Alcohol: (.+?) · Exercise: (.+?)$", "धूम्रपान: $1 · शराब: $2 · कसरत: $3"], ["^(.+?) · asked by (.+?) · (.+?)$", "$1 · $2 ने माँगा · $3"], ["^(.+?) · can add records$", "$1 · रिकॉर्ड जोड़ सकते हैं"], ["^Normal: (.+?) · from your lab report$", "सामान्य: $1 · आपकी लैब रिपोर्ट से"], ["^Normal: (.+?)$", "सामान्य: $1"], ["^Source evidence · page (\\d+)$", "स्रोत का प्रमाण · पृष्ठ $1"], ["^(.+?) · reading confidence (\\d+)%$", "$1 · पढ़ने की विश्वसनीयता $2%"], ["^(.+?) · starts (.+?) · take till (.+?)$", "$1 · शुरू: $2 · $3 तक लें"], ["^(.+?) · starts (.+?) · (\\d+) days$", "$1 · शुरू: $2 · $3 दिन"], ["^(.+?) · starts (.+?) · until stopped$", "$1 · शुरू: $2 · बंद किए जाने तक"], ["^(.+?) · starts (.+?) · choose treatment end$", "$1 · शुरू: $2 · इलाज की समाप्ति चुनें"], ["^(\\d+)× in symptom checks$", "$1× लक्षण जाँचों में"], ["^(.+?) — check against the original$", "$1 — मूल रिपोर्ट से मिलान करें"], ["^(.+?) — possible: (.+?)$", "$1 — संभावित: $2"], ["^Compared with (.+?)$", "$1 से तुलना"], ["^⚠ Overlaps with <b>(.+?)<\\/b> at (.+?)\\. Save anyway\\?$", "⚠ <b>$1</b> से टकराव, $2 पर। फिर भी सहेजें?"], ["^Marked as better: (.+?)$", "बेहतर चिह्नित: $1"], ["^Gentle ideas for (.+?)$", "@1 के लिए कोमल सुझाव"]];
